#include <iostream>
using namespace std;

class Account {
    double balance_ = 0;

public:
    bool deposit(double amount) {
        if (amount <= 0) {
            return false;
        }
        balance_ += amount;
        return true;
    }
    double balance() const { return balance_; }
};

int main() {
    Account acc;
    acc.deposit(500);
    cout << boolalpha << acc.deposit(-20) << endl;
    cout << acc.balance() << endl;
    return 0;
}

#include <iostream>
using namespace std;

class Person {
    int age_ = 0;

public:
    int age() const { return age_; }
    void set_age(int age) {
        if (age >= 0 && age <= 120) {
            age_ = age;
        }
    }
};

int main() {
    Person p;
    p.set_age(17);
    p.set_age(500);
    cout << p.age() << endl;
    return 0;
}

